// Kobble's routes for the Signals and Personas pages, and the sync with the
// live app. Like every button, a POST is answered only from the factory's
// page (server.ts). Each change is told on the page's stream as a
// `kobble-changed` event; the page reads what it shows again.
import { join } from "node:path";
import { FACTORY_FOLDER, KobbleRefused, KobbleStore, } from "@software-factory/core";
import { asked, field } from "../asked.js";
import { cardsFor, NO_BOARD } from "../cards/cards-for.js";
import { Refused } from "../refused.js";
import { addPersona, dismissSignal, exploreSignal, fixSignal, } from "./actions.js";
import { branchParts, servedExplorations } from "./explorations/routes.js";
import { explorationRoutes, storeOf, usageOf } from "./usage-routes.js";
import { liveSettings } from "./live-source.js";
import { MissionIdeas } from "./mission-ideas.js";
import { PersonaTests } from "./persona-tests.js";
import { LiveSync } from "./sync.js";
import { connect, disconnect } from "./connect.js";
import { boardIdeas, factoryView } from "./factory-view.js";
import { supportOf, supportRoutes } from "./support.js";
import { handledView, personaPage, personasView, signalsView, testPage, testsOf, } from "./views.js";
export function servedKobble(options) {
    const factory = join(options.project, FACTORY_FOLDER);
    const changed = (what) => {
        options.tell(`event: kobble-changed\ndata: ${JSON.stringify({ what })}\n\n`);
    };
    const { maybe, store } = storesOf(factory, options.project);
    const sync = new LiveSync({
        store: maybe,
        settings: () => liveSettings(options.project),
        onSynced: () => {
            changed("signals");
        },
    });
    const changing = changingWith(changed);
    const { explorations, tests } = explorationsAndTests(options, store, changed);
    const support = supportOf(options, store, changed);
    const routes = {
        "GET /api/kobble/signals": () => kept(() => signalsView(store(), sync.view(), options.work())),
        "GET /api/kobble/factory": () => kept(() => factoryView(store(), options.work())),
        "POST /api/kobble/sync": async () => {
            const added = await sync.sync();
            return { added: added.length, sync: sync.view() };
        },
        ...liveRoutes(options.project, sync, changed),
        "GET /api/kobble/handled": () => kept(() => handledView(store())),
        ...buttonRoutes(store, changing, () => connectedCards(factory, options.cli)),
        ...tests.routes,
        ...supportRoutes(support),
        ...keptAll(explorationRoutes(explorations, tests.tests, () => usageOf(factory, options.project))),
    };
    return {
        routes,
        // Where the server answers the kobold's board tools.
        serveToolsAt: (base) => {
            explorations.talks.serveToolsAt(`${base}/kobble/explorations/mcp`);
            explorations.prototypes.serveWorldAt(`${base}/kobble/world`);
            support.serveToolsAt(`${base}/kobble/support/mcp`);
        },
        boardTools: (id) => explorations.talks.tools(id),
        supportTools: () => support.tools(),
        // The made-up worlds the prototypes share (world-route.ts).
        worlds: explorations.worlds,
        start: () => {
            if (maybe())
                tests.recover();
            sync.start();
        },
        close: () => {
            sync.close();
            explorations.close();
        },
    };
}
// The records once the factory is there; none in setup (maybe), or
// refused (store).
function storesOf(factory, project) {
    const maybe = () => storeOf(factory, project);
    const store = () => {
        const found = maybe();
        if (!found)
            throw new Refused("There is no factory yet: its records come with it.");
        return found;
    };
    return { maybe, store };
}
// A change to the records, told to the page; a record that does not fit is
// refused with why.
function changingWith(changed) {
    return (what, act) => async (body, url) => {
        const answer = await kept(() => act(body, url));
        changed(what);
        return answer;
    };
}
// Connecting the live app and disconnecting it; each sync starts again.
function liveRoutes(project, sync, changed) {
    return {
        "POST /api/kobble/connect": async (body) => {
            const { ignored } = await connect(project, body);
            sync.start();
            changed("signals");
            return { ignored, sync: sync.view() };
        },
        "POST /api/kobble/disconnect": () => {
            disconnect(project);
            sync.close();
            changed("signals");
            return { sync: sync.view() };
        },
    };
}
// The connected board's cards; refused with how to connect one when there
// is none.
export function connectedCards(factory, cli) {
    const found = cardsFor(factory, cli);
    if ("problem" in found)
        throw new Refused([
            "No GitHub board is connected yet, so there is nowhere to put it.",
            ...(found.problem === NO_BOARD ? [] : [found.problem]),
            "Connect one in [Settings](#settings), under Where work is tracked.",
        ].join(" "));
    return found.cards;
}
// The explorations, and persona tests, which may run on a prototype of one.
function explorationsAndTests(options, store, changed) {
    const factory = join(options.project, FACTORY_FOLDER);
    const explorations = servedExplorations({
        project: options.project,
        root: factory,
        claude: options.claude,
        store,
        cards: () => connectedCards(factory, options.cli),
        ideas: () => boardIdeas(options.work()),
        onChange: () => {
            changed("explorations");
        },
    });
    const tests = testRoutes(options, store, {
        onChange: () => {
            changed("tests");
        },
        prototype: (on, persona) => {
            const parts = branchParts(on);
            if (!parts)
                throw new Refused(`“${on}” is not a prototype's branch.`);
            return explorations.prototypes.address(parts.exploration, parts.key, persona);
        },
    });
    return { explorations, tests };
}
// Persona tests (missions): the one the kobold suggests, start one, a
// persona's tests, one test.
function testRoutes(options, store, more) {
    const tests = new PersonaTests({
        claude: options.claude,
        cwd: options.project,
        store,
        app: (test) => test.on === "main"
            ? options.testsRunOn.app(test.product ?? null)
            : more.prototype(test.on, test.persona),
        browser: options.testsRunOn.browser,
        onChange: more.onChange,
    });
    const ideas = new MissionIdeas({
        claude: options.claude,
        cwd: options.project,
        store,
        apps: options.testsRunOn.apps,
    });
    const routes = {
        "GET /api/kobble/mission": (_body, url) => kept(async () => ({
            mission: await ideas.suggest(asked(url, "persona", "persona"), url.searchParams.get("again") === "yes"),
        })),
        "GET /api/kobble/tests": (_body, url) => kept(() => ({
            tests: testsOf(store(), asked(url, "persona", "persona")),
        })),
        "GET /api/kobble/test": (_body, url) => kept(() => testPage(store(), asked(url, "id", "test"))),
        "POST /api/kobble/tests": (body) => kept(() => {
            const test = tests.start(body);
            ideas.forget(test.persona);
            return { test };
        }),
    };
    return {
        routes,
        tests,
        recover: () => {
            tests.recover();
        },
    };
}
// Routes whose records may not fit: refused with why.
function keptAll(routes) {
    return Object.fromEntries(Object.entries(routes).map(([name, route]) => [
        name,
        (body, url) => kept(() => route(body, url)),
    ]));
}
// The buttons: Fix, Explore (or Add to), Dismiss; the personas, and New
// persona.
function buttonRoutes(store, changing, cards) {
    return {
        "GET /api/kobble/personas": () => kept(() => personasView(store())),
        "GET /api/kobble/persona": (_body, url) => kept(() => personaPage(store(), asked(url, "id", "persona"))),
        "POST /api/kobble/signals/fix": changing("signals", async (body) => ({
            signal: await fixSignal(store(), field(body, "id"), cards),
        })),
        "POST /api/kobble/signals/explore": changing("signals", (body) => exploreSignal(store(), field(body, "id"))),
        "POST /api/kobble/signals/dismiss": changing("signals", (body) => ({
            signal: dismissSignal(store(), field(body, "id")),
        })),
        "POST /api/kobble/personas": changing("personas", (body) => ({
            persona: addPersona(store(), body),
        })),
    };
}
// What the records answer; a file that does not fit is refused with why.
async function kept(read) {
    try {
        return await read();
    }
    catch (error) {
        if (error instanceof KobbleRefused)
            throw new Refused(error.message);
        throw error;
    }
}
